#!/bin/bash
# Task 137-w10-split-ab -- meshsim sim/ WORKER10 (branch sim-w10; kit: before 45b4cbf, after 2e016ea). TIMING TASK: keep the box quiet while it runs.
# The cheaper split (W10, piece 1), before and after in one task, interleaved run by run:
# before = 45b4cbf (Quest 136's framework), after = 2e016ea (domains grouped into one engine per thread; also the
# Link with depth, the port observer, the stop request: no cost expected on these chips).
# The speed matrix of Quest 136 for both (one thread with perf; split on one thread; form 2 by rows, by tiles, synth over
# 2/4/P/8/all-P threads), plus W4's layout on the after (--engines: 6 and 64 engines on one thread, the split's own cost);
# VERDICT one digest per chip and rate across both revisions; summary.txt. 5 repeats. Expected ~20 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/137-w10-split-ab/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/137-w10-split-ab; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-137-w10-split-ab; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "e9b95242589d377039d0e73d99e12956307a1e70a149cd15a2f34e8e497fa17e" ] || { echo "kit sha256 mismatch (want e9b95242589d377039d0e73d99e12956307a1e70a149cd15a2f34e8e497fa17e)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="before after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: before 45b4cbf, after 2e016ea"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^threads ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): the speed matrix, for every kit revision in $KITS, interleaved run by run. Used for the baseline
# (one revision) and for each change's before/after (two). The machine from machine.sh (D21): PLACE, P_ONE, P_CPUS, take,
# count. REPS (default 5) repeats; CYC (default 60000) cycles per run.
REPS=${REPS:-5}; CYC=${CYC:-60000}
sec "build (clang release, D18) and the thread tests (clang debug: ASan, UBSan), per revision"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_threads > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=debug build/clang-debug/test_threads build/clang-debug/test_matrix >> "$RES/build-$k.log" 2>&1 \
    && ./build/clang-debug/test_threads > /dev/null && ./build/clang-debug/test_matrix > /dev/null ) \
    && verdict "test_threads, test_matrix (debug) $k" PASS || verdict "test_threads, test_matrix (debug) $k" FAIL
done
NP=$(count "$P_ONE"); NPC=$(count "$P_CPUS"); P1=$(take 1 "$P_ONE")
V="--form 2 --cycles $CYC --warmup 2000"
cpus_for() { local t=$1; if [ "$t" -le "$NPC" ]; then echo "$P_CPUS"; else echo "$ALL_CPUS"; fi; }   # the taskset: P CPUs while they suffice
TS=; for t in 2 4 $NP 8 $NPC; do [[ " $TS " == *" $t "* ]] || TS+="${TS:+ }$t"; done                 # thread counts, P cores first then hyperthreads

sec "1. one thread, one domain: mesh at rate 0.35 and 0.05, the synthetic chip; perf stat; $REPS repeats"
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  PERF=1 run "$k one-mesh35" "$P1" $B $V --rate 0.35 --threads 1 --cpus "$P1"
  PERF=1 run "$k one-mesh05" "$P1" $B $V --rate 0.05 --threads 1 --cpus "$P1"
  PERF=1 run "$k one-synth" "$P1" $B $V --chip synth --threads 1 --cpus "$P1"
done; done

sec "2. the split's own cost on one thread: mesh by rows (2, 4, 6, 8 domains) and by tiles (64); synth by clusters (8); $REPS repeats"
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  for d in 2 4 6 8; do run "$k split1-rows$d" "$P1" $B $V --threads 1 --domains $d --cpus "$P1"; done
  PERF=1 run "$k split1-tiles64" "$P1" $B $V --threads 1 --partition tiles --cpus "$P1"
  run "$k split1-synth8" "$P1" $B $V --chip synth --threads 1 --partition tiles --cpus "$P1"
done; done

sec "2b. W4's layout, for revisions that have it (Options::engines, a measurement option): one thread running 6 and 64 engines; $REPS repeats"
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  grep -q -- '--engines' "$W/kit/$k/sim/bench/threads/bench_threads.cpp" || continue
  run "$k eng1-rows6" "$P1" $B $V --threads 1 --domains 6 --engines 6 --cpus "$P1"
  run "$k eng1-tiles64" "$P1" $B $V --threads 1 --partition tiles --engines 64 --cpus "$P1"
done; done

sec "3. form 2: mesh by rows (T domains, T <= 8) and by tiles (64 domains), synth by clusters (8 domains), over T = $TS threads (placement: $PLACE); $REPS repeats"
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  for t in $TS; do C=$(take $t "$PLACE"); TSET=$(cpus_for $t)
    [ "$t" -le 8 ] && run "$k t$t-rows" "$TSET" $B $V --threads $t --cpus "$C"
    run "$k t$t-tiles64" "$TSET" $B $V --threads $t --partition tiles --cpus "$C"
    [ "$t" -le 8 ] && run "$k t$t-synth8" "$TSET" $B $V --chip synth --threads $t --partition tiles --cpus "$C"
  done
done; done

sec "4. digests: one per chip and rate over every run and revision"
for key in "chip=mesh .*rate_in=0.35" "chip=mesh .*rate_in=0.05" "chip=synth "; do
  n=$(grep -E "$key" "$RES/raw.txt" | field digest | sort -u | wc -l)
  [ "$n" = 1 ] && verdict "digests ($key)" PASS || verdict "digests ($key): $n distinct" FAIL
done

sec "5. summary: medians, us per chip-cycle (wall), words (Sizes), and against one thread"
for k in $KITS; do
  base=$(med "$k one-mesh35" us_per_chip_cycle); sb=$(med "$k one-synth" us_per_chip_cycle)
  for tag in one-mesh35 one-mesh05 one-synth split1-rows2 split1-rows4 split1-rows6 split1-rows8 split1-tiles64 split1-synth8 \
             eng1-rows6 eng1-tiles64 \
             $(for t in $TS; do echo t$t-rows t$t-tiles64 t$t-synth8; done); do
    u=$(med "$k $tag" us_per_chip_cycle); [ "$u" = - ] && continue
    w=$(med "$k $tag" words); case $tag in *synth*) b=$sb ;; one-mesh05) b=$u ;; *) b=$base ;; esac
    printf "%-6s %-16s us=%-8s x_one=%-6s words=%s\n" "$k" "$tag" "$u" "$(awk -v b="$b" -v u="$u" 'BEGIN { printf "%.2f", b / u }')" "$w"
  done
done | tee "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
